    .await
    .map_err(|source| {
        ProductionDevStageError::owner("load the exact release snapshot", source)
    })?;
    self.read_publisher
        .set_release(release.manifest, release.carrier.clone());
    self.release = Some(release.carrier);
    Ok(())
}

