//! Pre-apply validation for package-owned PostgreSQL migration artifacts.
//!
//! `docs/architecture/application-naming.md` owns schema selection: migrations
//! author it and therefore require qualified DDL, while SQL corpora inherit the
//! host-selected `search_path` and refuse qualified references. This is the same
//! boundary frozen in `wamn:postgres@0.1.0`, where the host selects the schema
//! and guests name relations unqualified.
//!
//! The validator intentionally admits only the DDL shapes currently demanded by
//! Receiving: schema-qualified ordinary `CREATE TABLE`, one additive client
//! column, or one named client check constraint. PostgreSQL remains responsible
//! for parsing definitions, while post-apply catalog introspection validates
//! their resulting objects. This layer refuses statement operations that the
//! final catalog state cannot prove.

use std::ffi::OsStr;
use std::fmt;
use std::fs;
use std::io;
use std::path::{Path, PathBuf};

/// Stable internal class for a refused migration artifact.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum MigrationPolicyErrorKind {
    NotSqlArtifact,
    ArtifactRead,
    EmptyArtifact,
    InvalidSql,
    SetRole,
    RoleOperation,
    GrantOperation,
    NontransactionalOperation,
    CrossSchemaMutation,
    UnnamedConstraint,
    ConstraintNameTooLong,
    RuledOperation,
    UnsupportedStatement,
}

/// Managed PostgreSQL definition addressed by a migration statement.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum DefinitionKind {
    Relation,
    Field,
    Constraint,
}

impl DefinitionKind {
    /// Stable catalog spelling for the ownership ledger.
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Relation => "relation",
            Self::Field => "field",
            Self::Constraint => "constraint",
        }
    }
}

/// Structural action one migration statement takes on a managed definition.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum DefinitionAction {
    Create,
    Add,
    Alter,
    Drop,
}

/// One schema-qualified definition mutation extracted by the migration loader.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct DefinitionMutation {
    action: DefinitionAction,
    kind: DefinitionKind,
    schema: Box<str>,
    relation: Box<str>,
    definition: Box<str>,
    statement_index: usize,
}

impl DefinitionMutation {
    /// Structural action applied to the definition.
    pub const fn action(&self) -> DefinitionAction {
        self.action
    }

    /// Definition grain addressed by the statement.
    pub const fn kind(&self) -> DefinitionKind {
        self.kind
    }

    /// Schema selected explicitly by the migration.
    pub fn schema(&self) -> &str {
        &self.schema
    }

    /// Relation containing the definition.
    pub fn relation(&self) -> &str {
        &self.relation
    }

    /// Unqualified definition name; relation actions repeat the relation name.
    pub fn definition(&self) -> &str {
        &self.definition
    }

    /// One-based statement position inside the artifact.
    pub const fn statement_index(&self) -> usize {
        self.statement_index
    }
}

/// Contextual refusal from the migration-artifact boundary.
#[derive(Debug)]
pub struct MigrationPolicyError {
    kind: MigrationPolicyErrorKind,
    path: PathBuf,
    statement_index: Option<usize>,
    detail: Box<str>,
    source: Option<io::Error>,
}

impl MigrationPolicyError {
    /// Stable class for callers that must not match display text.
    pub const fn kind(&self) -> MigrationPolicyErrorKind {
        self.kind
    }

    /// SQL artifact that was refused.
    pub fn path(&self) -> &Path {
        &self.path
    }

    /// One-based statement index when the refusal belongs to a statement.
    pub const fn statement_index(&self) -> Option<usize> {
        self.statement_index
    }
}

impl fmt::Display for MigrationPolicyError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(formatter, "migration {}", self.path.display())?;

