//! The wire scalars every operation parses, spelled once.
//!
//! Parse and RE-SPELL, not merely validate. The canonicalization contract
//! fixes uuids as lowercase-hyphenated and timestamps as UTC RFC 3339 with six
//! fractional digits, so a caller's spelling must reach the database -- and the
//! command bytes -- in one form. Two deliveries of the same command would
//! otherwise canonicalize differently and the idempotency key would stop
//! working.

use wamn_postgres_statements::{TimestampTz, Uuid};

use crate::error::{AccessError, AccessErrorKind};

/// One UTC day, as the half-open timestamp interval a query filters on.
#[derive(Clone, Debug, Eq, PartialEq)]
pub(crate) struct DayBounds {
    pub(crate) start: TimestampTz,
    pub(crate) end: TimestampTz,
}

pub(crate) fn uuid(field: &str, value: &str) -> Result<Uuid, AccessError> {
    value
        .parse::<uuid::Uuid>()
        .map(|parsed| Uuid(parsed.hyphenated().to_string()))
        .map_err(|_| AccessError::field(AccessErrorKind::InvalidInput, field))
}

pub(crate) fn timestamp(field: &str, value: &str) -> Result<TimestampTz, AccessError> {
    chrono::DateTime::parse_from_rfc3339(value)
        .map(|parsed| TimestampTz(parsed.to_utc().format("%Y-%m-%dT%H:%M:%S%.6fZ").to_string()))
        .map_err(|_| AccessError::field(AccessErrorKind::InvalidInput, field))
}

/// A `YYYY-MM-DD` day, widened to the UTC interval `[00:00, next 00:00)`.
///
/// THE DAY IS UTC. An appointment slot is a `timestamptz`, so "one dock's
/// appointments for a day" needs a zone to be a question at all, and the
/// package answers in the one zone every other timestamp it emits is spelled
/// in. A dock in another zone would need its own offset, which the scenario
/// does not give it.
pub(crate) fn day_bounds(field: &str, value: &str) -> Result<DayBounds, AccessError> {
    let refuse = || AccessError::field(AccessErrorKind::InvalidInput, field);
    let day = chrono::NaiveDate::parse_from_str(value, "%Y-%m-%d").map_err(|_| refuse())?;
    // `parse_from_str` accepts `2026-1-1`, and the contract's day is written
    // with two-digit parts, so the round trip is what admits it.
    if day.format("%Y-%m-%d").to_string() != value {
        return Err(refuse());
    }
    let next = day.succ_opt().ok_or_else(refuse)?;
    Ok(DayBounds {
        start: TimestampTz(format!("{day}T00:00:00.000000Z")),
        end: TimestampTz(format!("{next}T00:00:00.000000Z")),
    })
}

/// The appointment status a query filters on, and nothing outside the enum.
pub(crate) fn appointment_status(field: &str, value: &str) -> Result<String, AccessError> {
    match value {
        "scheduled" | "arrived" | "departed" => Ok(value.to_owned()),
        _ => Err(AccessError::field(AccessErrorKind::InvalidInput, field)),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn uuids_and_timestamps_are_respelled_canonically() {
        assert_eq!(
            uuid("f", "01234567-89AB-CDEF-0123-456789ABCDEF").unwrap().0,
            "01234567-89ab-cdef-0123-456789abcdef"
        );
        assert!(uuid("f", "not-a-uuid").is_err());
        assert_eq!(
            timestamp("f", "2026-10-01T11:00:00+02:00").unwrap().0,
            "2026-10-01T09:00:00.000000Z"
        );
        assert_eq!(
            timestamp("f", "2026-10-01T09:00:00Z").unwrap().0,
            "2026-10-01T09:00:00.000000Z"
        );
        assert!(timestamp("f", "yesterday").is_err());
    }

    /// The day is half-open: an appointment starting at the next midnight
    /// belongs to the next day, not to two days at once.
    #[test]
    fn a_day_is_the_half_open_utc_interval_it_names() {
        let bounds = day_bounds("f", "2026-10-01").unwrap();
        assert_eq!(bounds.start.0, "2026-10-01T00:00:00.000000Z");
        assert_eq!(bounds.end.0, "2026-10-02T00:00:00.000000Z");
        assert_eq!(
            day_bounds("f", "2026-12-31").unwrap().end.0,
            "2027-01-01T00:00:00.000000Z"
        );
        for refused in ["", "2026-1-1", "2026-13-01", "2026-10-01T00:00:00Z", "today"] {
            assert!(day_bounds("f", refused).is_err(), "{refused:?} must refuse");
        }
    }

    #[test]
    fn a_status_filter_is_one_of_the_three_the_enum_holds() {
        for admitted in ["scheduled", "arrived", "departed"] {
            assert_eq!(appointment_status("f", admitted).unwrap(), admitted);
        }
        assert!(appointment_status("f", "cancelled").is_err());
    }
}
